-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.validate_page_section_placement()
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.validate_page_section_placement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF jsonb_typeof(NEW.content) = 'array' AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(NEW.content) item
      JOIN public.section_defs d ON d.id::text = item->>'section_def_id'
     WHERE d.placement <> 'page') THEN
    RAISE EXCEPTION 'a site header or footer component cannot be placed in page content' USING ERRCODE = 'CMS04';
  END IF;
  RETURN NEW;
END
$function$
